package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
public final class ContextAutomaticModelBasisRunner {
 static int checks;static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static ContextSignedModelInspection.Automatic limits(int points,int fresh,int work){ContextSignedCandidateInspection.Limits n=new ContextSignedCandidateInspection.Limits(64,8,2,16,64000000,500000,64000000,64000000,64);return new ContextSignedModelInspection.Automatic(new ContextSignedModelInspection.Limits(n,512,16,8,64000000,16,64,64000000,16,16,8,64000000,65536,64000000),points,fresh,work);}
 static ContextSignedWitnessNativeBranch.Receipt branch(String text)throws Exception{return ContextSignedUnaryModelSearchMatrix.branch(ContextSignedUnaryModelMatrix.bind(true,text));}
 static void no(ContextSignedModelInspection.Result r){require(r.status==ContextSignedModelInspection.Status.INCOMPLETE&&r.proposed==null&&r.oppositions.isEmpty()&&r.basisAttempts==0,"atomic automatic-basis INCOMPLETE, not refutation");}
 public static void main(String[] args)throws Exception{
  ContextSignedWitnessNativeBranch.Receipt b=branch("!p(0); !q(1);");List<List<SemanticTermSnapshot>> plans=ContextSignedModelBasis.plan(b,limits(4,2,64000000));require(plans.size()==3&&plans.get(0).size()==2&&plans.get(2).size()==4,"minimal COMPLETE constants first, then bounded fresh growth");SemanticTermSnapshot two=ContextSignedEligibilityMatrix.value(2);require(plans.get(1).get(2).semanticallyEquals(two),"native numeric factory skips semantic collisions0/1, produces ordinary2");try{plans.get(0).clear();throw new AssertionError();}catch(UnsupportedOperationException expected){require(true,"immutable candidate points");}try{plans.clear();throw new AssertionError();}catch(UnsupportedOperationException expected){require(true,"immutable candidate plan");}
  ContextSignedModelInspection.Result r=ContextSignedModelInspection.inspectAutomatic(b.x,b.foreign,limits(4,2,64000000));require(r.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&r.namedPoints==2&&r.basisAttempts==1,"minimal successful basis used before pointless model blowup");
  b=branch("!p(7); !~q('7');");plans=ContextSignedModelBasis.plan(b,limits(4,0,64000000));require(plans.get(0).size()==2&&!plans.get(0).get(0).semanticallyEquals(plans.get(0).get(1)),"typed numeric/string constants not deduplicated by text");
  b=branch("!$u p(u); !$u ~p(u);");no(ContextSignedModelInspection.inspectAutomatic(b.x,b.foreign,limits(4,1,64000000)));r=ContextSignedModelInspection.inspectAutomatic(b.x,b.foreign,limits(4,2,64000000));require(r.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&r.namedPoints==2&&r.basisAttempts==2,"one-point failure then genuinely fresh two-point model SAME actual branch");no(ContextSignedModelInspection.inspectAutomatic(b.x,b.foreign,limits(4,0,64000000)));
  b=branch("!$u p(u); !$u q(u);");r=ContextSignedModelInspection.inspectAutomatic(b.x,b.foreign,limits(4,2,64000000));require(r.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&r.namedPoints==1&&r.basisAttempts==1,"separate Origin Sources CAN coincide; fresh values not a disequality policy");
  b=branch("!p(0); !q(1);");no(ContextSignedModelInspection.inspectAutomatic(b.x,b.foreign,limits(1,2,64000000)));no(ContextSignedModelInspection.inspectAutomatic(b.x,b.foreign,limits(4,2,1)));
  Snapshot x=ContextSignedUnaryModelMatrix.bind(true,"!anchor(1); !@u seed(u)->blocked(u);"),a=ContextSignedUnaryModelMatrix.bind(false,"!$u seed(u)&&~blocked(u);");r=ContextSignedModelInspection.inspectAutomatic(x,Collections.singletonList(a),limits(1,0,1));require(r.status==ContextSignedModelInspection.Status.REFUTED&&!r.oppositions.isEmpty()&&r.basisAttempts==0,"native signed proof precedes unavailable basis/work, never failed search=>conflict");
  Snapshot group=ContextProductionNativeBinding.trusted("basis",Arrays.asList(ContextSignedUnaryModelMatrix.bind(false,"!p(7);"),ContextSignedUnaryModelMatrix.bind(false,"!~q('7');")),64000000);ContextSignedWitnessNativeBranch.Result nativeBranch=ContextSignedWitnessNativeBranch.run(ContextSignedUnaryModelMatrix.bind(true,"!~anchor(0);"),Collections.singletonList(group),ContextSignedWitnessNativeMatrix.policy());require(nativeBranch.output!=null,nativeBranch.reason);plans=ContextSignedModelBasis.plan(nativeBranch.output,limits(4,0,64000000));require(plans.get(0).size()==3,"all TRUST physical constants retained plus root constant");
  System.out.println("AUTOMATIC_MODEL_BASIS minimalConstants=true typedSemanticDedup=true nativeFreshValues=true noOriginInequality=true boundedGrowthNotConflict=true proofFirst=true");System.out.println("CONTEXT_AUTOMATIC_MODEL_BASIS_PASS checks="+checks);
 }
}
